  # component.  It is compiled with the build GHC and *runs on the build
  # machine* (not the target machine), so it must be built with the build
  # stdenv (`buildPackages.stdenv`) rather than the (possibly cross)
  # stdenv used for the components themselves.  Using the cross stdenv
  # here would, for example, run the target's own fixup/strip tools on
  # what is actually a native (build platform) executable.  This matters
  # when cross-compiling (e.g. for Windows or aarch32 targets).
  setup-builder = haskellLib.weakCallPackage pkgs ./setup-builder.nix {
    ghc = (ghc.passthru.buildGHC or ghc);
    hsPkgs = hsPkgs.buildPackages;
    inherit buildPackages pkgconfig;
