import sys

def analyze(path):
    s = open(path).read()
    i = 0; n = len(s); db = 0; dp = 0; line = 1
    neg = None
    def update(ch, ln):
        nonlocal db, dp, neg
        if ch == '{': db += 1
        elif ch == '}': db -= 1
        elif ch == '(': dp += 1
        elif ch == ')': dp -= 1
        if db < 0 and neg is None: neg = ('{', ln)
        if dp < 0 and neg is None: neg = ('(', ln)

    while i < n:
        c = s[i]
        if c == '\n': line += 1
        if c == '#':
            while i < n and s[i] != '\n': i += 1
            continue
        if c == '"':
            update(c, line); i += 1
            while i < n:
                if s[i] == '\\': i += 2; continue
                if s[i] == '"': i += 1; break
                if s[i] in '${\n': pass
                if s[i] == '$' and i+1 < n and s[i+1] == '{':
                    j = i + 2  # skip ${
                    while j < n:
                        e = s[j]
                        if e == '\n': line += 1
                        if e == '#':
                            while j < n and s[j] != '\n': j += 1
                            continue
                        if e == '"':
                            j += 1
                            while j < n:
                                if s[j] == '\\': j += 2; continue
                                if s[j] == '"': j += 1; break
                                j += 1
                            continue
                        if e == '{': db += 1
                        elif e == '}':
                            db -= 1
                            if db < 0 and neg is None and False: pass
                            if db == 0:
                                j += 1; break
                        elif e == '(': dp += 1
                        elif e == ')': dp -= 1
                        j += 1
                    i = j
                    continue
                i += 1
            continue
        if c == "'" and i+1 < n and s[i+1] == "'":
            update(c, line); i += 2
            while i < n:
                if s[i] == '\\' and i+1 < n and s[i+1] in "'$":
                    i += 2; continue
                if s[i] == "'" and i+1 < n and s[i+1] == "'":
                    i += 2; break
                if s[i] == '$' and i+1 < n and s[i+1] == '{':
                    j = i + 2
                    while j < n:
                        e = s[j]
                        if e == '\n': line += 1
                        if e == '{': db += 1
                        elif e == '}':
                            db -= 1
                            if db == 0:
                                j += 1; break
                        elif e == '(': dp += 1
                        elif e == ')': dp -= 1
                        elif e == '"':
                            j += 1
                            while j < n:
                                if s[j] == '\\': j += 2; continue
                                if s[j] == '"': j += 1; break
                                j += 1
                            continue
                        j += 1
                    i = j
                    continue
                i += 1
            continue
        update(c, line)
        i += 1
    return db, dp, neg

if __name__ == '__main__':
    print(analyze(sys.argv[1]))

