import sys

def tokenize(s, i=0, depth_brace=0, depth_paren=0, depth_brack=0, indent="", cap=None):
    """Count {} () [] outside strings/comments. Handles ${} interpolation recursively."""
    n = len(s)
    diag = []
    while i < n:
        c = s[i]
        if c == '#':
            while i < n and s[i] not in '\n': i += 1
            continue
        if c == '"':
            i += 1
            while i < n:
                if s[i] == '\\':
                    i += 2; continue
                if s[i] == '$' and i+1 < n and s[i+1] == '{':
                    db = 1
                    j = i + 2
                    while j < n:
                        if s[j] == '{': db += 1
                        elif s[j] == '}':
                            db -= 1
                            if db == 0:
                                j += 1; break
                        j += 1
                    i = j
                    continue
                if s[i] == '"':
                    i += 1; break
                i += 1
            continue
        if c == "'" and i+1 < n and s[i+1] == "'":
            i += 2
            while i < n:
                if s[i] == "'" and i+1 < n and s[i+1] == "'":
                    i += 2; break
                if s[i] == '$' and i+1 < n and s[i+1] == '{':
                    db = 1
                    j = i + 2
                    while j < n:
                        if s[j] == '{': db += 1
                        elif s[j] == '}':
                            db -= 1
                            if db == 0:
                                j += 1; break
                        j += 1
                    i = j
                    continue
                i += 1
            continue
        if c == '{':
            depth_brace += 1
            diag.append((i, 'brace+'))
        elif c == '}':
            depth_brace -= 1
            diag.append((i, 'brace-'))
            if depth_brace < 0:
                print('  NEG brace at pos', i, '->', repr(s[i-40:i+5]))
                return depth_brace, depth_paren, depth_brack
        elif c == '(':
            depth_paren += 1
        elif c == ')':
            depth_paren -= 1
        elif c == '[':
            depth_brack += 1
        elif c == ']':
            depth_brack -= 1
        i += 1
    return depth_brace, depth_paren, depth_brack

